_CONFLICT_CACHE = None


def _load_conflict_map():
    """加载矛盾关联映射（conflict_map.json：矛盾元数据 + 关联边）。"""
    global _CONFLICT_CACHE
    if _CONFLICT_CACHE is not None:
        return _CONFLICT_CACHE
    try:
        import os as _os
        _p = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)),
                           "conflict_map.json")
        with open(_p, encoding="utf-8") as _f:
            _CONFLICT_CACHE = json.load(_f)
    except Exception:
        _CONFLICT_CACHE = {"conflicts": {}, "links": []}
    return _CONFLICT_CACHE


def gen_conflict_links(question: str, answer: str = "", limit: int = 2) -> list:
    """回答命中实践智慧矛盾键 → 查关联矛盾 → 生成「相关矛盾」提示。

    例：「为什么婆婆总爱插手」→ 命中「婆媳相处」→ 关联 [夫妻协作, 代际观念]
    返回 [{'conflict': id, 'name': 名, 'note': 关联说明}]，最多 limit 条。
    """
    try:
        cmap = _load_conflict_map()
        meta = cmap.get("conflicts", {})
        links = cmap.get("links", [])
        if not meta:
            return []
        link_by_id = {}
        for l in links:
            link_by_id.setdefault(l["a"], []).append((l["b"], l["note"]))
            link_by_id.setdefault(l["b"], []).append((l["a"], l["note"]))
        # 命中实践智慧键（先答案后问题）
        # v1.26 修复（v6 关联）：触发词重叠时（「容貌焦虑」问题同时命中
        # 攀比心理/容貌焦虑），优先「键名完整出现在原文」的键——键名在
        # 原文 = 问题直接指向该矛盾；仅触发词命中 = 泛词（焦虑）间接命中。
        fp = encode(answer) if answer else {}
        hit = [t for t in fp if t in _KEY_TO_CONFLICT]
        if not hit:
            fp2 = encode(question)
            hit = [t for t in fp2 if t in _KEY_TO_CONFLICT]
        if not hit:
            return []
        # 键名在原文优先（容貌焦虑 in 问题 > 攀比心理 not in 问题）
        def _key_rank(t):
            in_q = 1 if t in question else 0
            return (in_q, fp.get(t, 0.0) if t in fp else
                    (encode(question).get(t, 0.0) if not answer else 0.0))
        hit.sort(key=_key_rank, reverse=True)
        cid = _KEY_TO_CONFLICT[hit[0]]
        out = []
        for rel_id, note in link_by_id.get(cid, [])[:limit]:
            m = meta.get(rel_id)
            if isinstance(m, dict):
                name = m.get("name", "?")
                q = m.get("q", "")
            else:
                name = m[0] if m else "?"
                q = ""
            out.append({"conflict": rel_id, "name": name, "note": note[:60],
                        "q": q})
        return out
    except Exception:
        return []


def main():
    argv = sys.argv[1:]
    index = load_human_index()

    if argv and argv[0] == '--index':
        print(f"翻译表覆盖：{len(SYNONYM_CLUSTERS)} 个规范词 / "
              f"{len(PHRASE_TABLE)} 条表达")
        for term, exprs in SYNONYM_CLUSTERS.items():
            print(f"  {term}: {len(exprs)} 种说法")
        return

    questions = argv or [
        "我肚子咕咕叫了",
        "今天打不起精神",
        "最近压力山大",
        "有点想哭",
        "眼皮打架了",
        "我火冒三丈",
        "心里七上八下的",
        "没人陪，有点孤单",
        "我饿了",
        "我冷静一下再说",
    ]
    print("=" * 66)
    print("智慧之书 · 知识翻译体系（编码解码系统）")
    print("理解 = 解码；翻译 = 条件空间对齐（VAL-SPEC-TRANSLATION-001）")
    print("=" * 66)
    for q in questions:
        print("\n【我问】" + q)
        show_trace(q, index)


if __name__ == '__main__':
    main()
